// Writes deploy/nginx/security-headers.conf from deploy/securityHeaders.js.
// Run after changing the headers: npm run headers:nginx
import { writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { securityHeaders } from './securityHeaders.js'

const target = fileURLToPath(new URL('./nginx/security-headers.conf', import.meta.url))
const lines = [
  '# Generated by `npm run headers:nginx` from deploy/securityHeaders.js. Do not edit by hand.',
  '# nginx drops server-level add_header lines inside any location that has its own add_header,',
  '# so include this file in every location block.',
  ...Object.entries(securityHeaders()).map(([name, value]) => `add_header ${name} "${value}" always;`),
  '',
]
writeFileSync(target, lines.join('\n'))
console.log(`Wrote ${target}`)
